from __future__ import annotations

import json
import os
import sys
import urllib.error
import urllib.request
from typing import Any, Iterator, Mapping

__all__ = ["ResponsesError", "send_prompt", "stream_prompt", "Reply"]

_DEFAULT_ENDPOINT = "https://api.openai.com/v1/responses"
_DEFAULT_MODEL = "gpt-4o-mini"


class ResponsesError(RuntimeError):
    """Raised when the OpenAI Responses API returns an error."""

    def __init__(self, status: int, message: str, payload: Mapping[str, Any] | None = None):
        super().__init__(f"HTTP {status}: {message}")
        self.status = status
        self.payload = dict(payload) if payload else {}


def _resolve_api_key(api_key: str | None) -> str:
    if api_key:
        return api_key
    env_key = os.environ.get("OPENAI_API_KEY")
    if not env_key:
        raise ResponsesError(
            401,
            "No API key provided. Set the OPENAI_API_KEY environment variable "
            "or pass api_key= [REDACTED_SECRET]",
        )
    return env_key


def _request(
    prompt: str,
    *,
    model: str,
    api_key: str,
    endpoint: str,
    stream: bool,
    extra_body: Mapping[str, Any] | None,
) -> urllib.request.Request:
    body: dict[str, Any] = {"model": model, "input": prompt}
    if stream:
        body["stream"] = True
    if extra_body:
        body.update(extra_body)
    return urllib.request.Request(
        endpoint,
        data=json.dumps(body).encode("utf-8"),
        method="POST",
        headers={
            "Authorization": f"Bearer {api_key}",
            "Content-Type": "application/json",
            "Accept": "text/event-stream" if stream else "application/json",
            "User-Agent": "openai_client.py/1.0",
        },
    )


def _safe_json(raw: bytes) -> Mapping[str, Any] | None:
    if not raw:
        return None
    try:
        decoded = json.loads(raw.decode("utf-8"))
    except (UnicodeDecodeError, json.JSONDecodeError):
        return None
    return decoded if isinstance(decoded, Mapping) else None


def _error_message(payload: Mapping[str, Any] | None) -> str:
    if not payload:
        return ""
    error = payload.get("error")
    if isinstance(error, Mapping):
        return str(error.get("message") or error.get("type") or "")
    return ""


def _post_json(request: urllib.request.Request, timeout: float | None) -> Mapping[str, Any]:
    opener_args: dict[str, Any] = {}
    if timeout is not None:
        opener_args["timeout"] = timeout
    try:
        with urllib.request.urlopen(request, **opener_args) as response:
            raw = response.read()
    except urllib.error.HTTPError as err:
        raw = err.read() if hasattr(err, "read") else b""
        payload = _safe_json(raw)
        message = _error_message(payload) or raw.decode("utf-8", errors="replace") or str(err.reason)
        raise ResponsesError(err.code, message, payload) from None
    except urllib.error.URLError as err:
        raise ResponsesError(0, f"Network error: {err.reason}") from None

    payload = _safe_json(raw)
    if payload is None:
        raise ResponsesError(200, "Could not decode response JSON")
    return payload


