        return f\"Reply(model={model"'!r}, text={self.text!r})"


def send_prompt(
    prompt: str,
    *,
    model: str = _DEFAULT_MODEL,
    api_key: str | None = None,
    endpoint: str = _DEFAULT_ENDPOINT,
    extra_body: Mapping[str, Any] | None = None,
    timeout: float | None = 30.0,
) -> Reply:
    """Send a text prompt to the Responses API and return the assistant reply.

    Parameters
    ----------
    prompt:
        The user-visible text prompt. Kept private: this module never logs it
        and only sends it to the configured ``endpoint``.
    model:
        Model identifier (defaults to ``gpt-4o-mini``).
    api_key:
        Bearer token. Defaults to ``$OPENAI_API_KEY``.
    endpoint:
        Override for the API URL (useful for tests/proxies).
    extra_body:
        Extra fields merged into the JSON body (e.g. ``instructions``).
    timeout:
        Request timeout in seconds, or ``None`` to wait forever.
