    request = _request(
        prompt,
        model=model,
        api_key=key,
        endpoint=endpoint,
        stream=False,
        extra_body=extra_body,
    )
    return Reply(_post_json(request, timeout))


def stream_prompt(
    prompt: str,
    *,
    model: str = _DEFAULT_MODEL,
    api_key: str | None = None,
    endpoint: str = _DEFAULT_ENDPOINT,
    extra_body: Mapping[str, Any] | None = None,
    timeout: float | None = 60.0,
) -> Iterator[str]:
    """Yield text deltas from the Responses API in streaming mode.

    The Responses API streams server-sent events when ``stream=true`` is set
    in the body. Each ``response.output_text.delta`` event carries a token chunk
    that is yielded in order.
    """
    if not isinstance(prompt, str) or not prompt.strip():
        raise ValueError("prompt must be a non-empty string")
    key = _resolve_api_key(api_key)
    request = _request(
        prompt,
        model=model,
        api_key=key,
        endpoint=endpoint,
        stream=True,
        extra_body=extra_body,
    )
    opener_args: dict[str, Any] = {}
    if timeout is not None:
        opener_args["timeout"] = timeout
    try:
        response = urllib.request.urlopen(request, **opener_args)
    except urllib.error.HTTPError as err:
        raw = err.read() if hasattr(err, "read") else b""
        payload = _safe_json(raw)
        message = _error_message(payload) or raw.decode("utf-8", errors="replace") or str(err.reason)
        raise ResponsesError(err.code, message, payload) from None
    except urllib.error.URLError as err:
        raise ResponsesError(0, f"Network error: {err.reason}") from None

    with response:
        for event_type, data in _iter_sse(response):
            if event_type == "response.output_text.delta":
                try:
                    parsed = json.loads(data)
                except json.JSONDecodeError:
                    continue
                delta = parsed.get("delta")
                if isinstance(delta, str):
                    yield delta


def _iter_sse(response: Any) -> Iterator[tuple[str, str]]:
    """Yield ``(event, data)`` pairs from an SSE response stream."""
    event: str | None = None
    data_lines: list[str] = []
    for chunk in response:
        text = chunk.decode("utf-8", errors="replace") if isinstance(chunk, bytes) else chunk
        for line in text.splitlines():
            if not line:
                if event is not None and data_lines:
                    yield event, "'"\\\\n\".join(data_lines)
                event = None
                data_lines = []
                continue
            if line.startswith(\":\"):
                continue
            field, _, value = line.partition(\":\")
            if value.startswith(\" \"):
                value = value[1:]
            if field == \"event\":
                event = value
            elif field == \"data\":
                data_lines.append(value)
    if event is not None and data_lines:
        yield event, \"\\\\n\".join(data_lines)


